func treeContentHash(t *testing.T, root string) string {
	t.Helper()
	var paths []string
	if err := filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !entry.IsDir() {
			rel, _ := filepath.Rel(root, path)
			rel = filepath.ToSlash(rel)
			vitalityLock := filepath.ToSlash(filepath.Join(brainstore.BrainLockDirName, factsVitalityLockName))
			if filepath.Base(path) == factsVitalityLogFileName ||
				filepath.Base(path) == factsVitalityRollupFileName ||
				rel == vitalityLock ||
				// The owner sidecar is part of the same artifact as the lock
				// above and is rewritten on the same acquisitions. It carries
				// the timestamp that used to live INSIDE the lock file, so
				// excluding the lock without its sidecar would make this hash
				// sensitive to the clock rather than to the brain.
				rel == vitalityLock+brainstore.FileLockOwnerSuffix {
				return nil
			}
			paths = append(paths, path)
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
func healthFixtureTree(t *testing.T, root string) map[string]string {
	t.Helper()
	result := map[string]string{}
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		if info.IsDir() {
			result[filepath.ToSlash(rel)+"/"] = info.Mode().String()
			return nil
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		result[filepath.ToSlash(rel)] = fmt.Sprintf("%s:%x", info.Mode(), data)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
func privacyTreeDigest(t *testing.T, root string) [32]byte {
	t.Helper()
	h := sha256.New()
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		_, _ = fmt.Fprintf(h, "%s\x00%d\x00", filepath.ToSlash(rel), len(data))
		_, _ = h.Write(data)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	var digest [32]byte
	copy(digest[:], h.Sum(nil))
	return digest
}
